parameters.jsCode:
const items = $input.all().map(i => i.json);
if (items.length === 0) return [];

const user = items[0];
const dateStr = new Date().toISOString().slice(0, 10);
const idempotencyKey = `digest:${user.user_id}:${dateStr}:${items.map(x => x.resume_version_id).join(',')}`;

const rowsHtml = items.map((job, idx) => `
  <div style="border:1px solid #d1d5db;border-radius:8px;padding:16px;margin-bottom:16px;font-family:sans-serif;">
    <h3 style="margin:0 0 6px 0;color:#111827;">${idx + 1}. ${job.title} — ${job.company} (${job.overall_match_score}/100)</h3>
    <p style="margin:4px 0;color:#4b5563;font-size:14px;">
      <strong>Location:</strong> ${job.location} (${job.work_mode}) |
      <strong>Posted:</strong> ${job.posted_at ? new Date(job.posted_at).toISOString().slice(0, 10) : 'N/A'} |
      <strong>Discovered:</strong> ${new Date(job.first_seen_at).toISOString().slice(0, 10)}
    </p>
    <p style="margin:8px 0;font-size:14px;"><strong>Why it matches:</strong> ${job.reasons_for_score}</p>
    <p style="margin:8px 0;font-size:14px;"><strong>Tailoring Summary:</strong> ${job.tailoring_summary}</p>
    <p style="margin:8px 0;font-size:13px;color:#b45309;">
      <strong>Missing Skills / Eligibility Notes:</strong> ${(job.missing_required_skills || []).join(', ') || 'None'}
    </p>
    <p style="margin:10px 0 4px 0;font-size:13px;">
      <strong>Resume Version ID:</strong> <code>${job.resume_version_id}</code><br/>
      <strong>Generated Files:</strong> ${job.docx_filename} / ${job.pdf_filename || 'N/A'}
    </p>
    <p style="margin:12px 0 0 0;">
      <a href="${job.application_url}" style="background:#2563eb;color:#ffffff;padding:8px 14px;text-decoration:none;border-radius:4px;font-size:13px;">Direct Application Link</a>
    </p>
  </div>
`).join('\n');

return [{
  json: {
    user_id: user.user_id,
    recipient: user.notification_target || user.user_email,
    channel: user.notification_method || 'email',
    subject: `[AI Job Digest] ${items.length} Qualifying Matches & Tailored Resumes (${dateStr})`,
    html_body: `<h2>Daily Tailored Job Digest for ${user.full_name}</h2>${rowsHtml}`,
    idempotency_key: idempotencyKey,
    job_ids: items.map(i => i.job_uuid),
    tailored_resume_ids: items.map(i => i.tailored_resume_id)
  }
}];

parameters.query:
INSERT INTO notifications (
  user_id, channel, notification_type, idempotency_key, recipient, subject, delivery_status, sent_at
) VALUES (
  $1, $2, 'daily_digest', $3, $4, $5, 'sent', NOW()
)
ON CONFLICT (idempotency_key) DO NOTHING
RETURNING id;
